INSERT INTO `course` VALUES (1,'Spring Boot 从入门到精通','https://wodiwodix-online-train-1259412410.cos.ap-guangzhou.myqcloud.com/images/2026/05/31/bb76904343674e60acc69fa894febac4.svg','全面讲解Spring Boot框架的使用，包括自动配置、Web开发、数据访问、安全认证等核心知识点',17,'ONLINE',0.00,1,1,1,'UP',1250,'已完结',NULL,NULL,3000,NULL,'2026-05-25 22:48:38','2026-05-31 14:19:48',0),(2,'Spring Cloud 微服务实战','https://wodiwodix-online-train-1259412410.cos.ap-guangzhou.myqcloud.com/images/2026/05/31/bb9ba424e0174e368524b43fcdd82a20.svg','深入讲解Spring Cloud Alibaba微服务架构，涵盖Nacos、Sentinel、Seata、Gateway等组件',1,'ONLINE',199.00,0,2,1,'UP',680,'更新中',NULL,NULL,3000,NULL,'2026-05-25 22:48:38','2026-05-31 14:19:48',0),(3,'Vue3 + TypeScript 实战','https://wodiwodix-online-train-1259412410.cos.ap-guangzhou.myqcloud.com/images/2026/05/31/077a3020c39e40d3ac64d9dca143399c.svg','从零到一掌握Vue3+TypeScript开发，包含Composition API、Pinia状态管理、Vite构建工具',2,'ONLINE',0.00,1,1,1,'UP',2100,'已完结',NULL,NULL,3000,NULL,'2026-05-25 22:48:38','2026-05-31 14:19:48',0),(4,'React18 全家桶实战','https://wodiwodix-online-train-1259412410.cos.ap-guangzhou.myqcloud.com/images/2026/05/31/9ec3b38198ca43ea9d0518fc505404a5.svg','React18新特性全面解析，Hooks、Redux Toolkit、Next.js、React Router全覆盖',2,'ONLINE',149.00,0,2,1,'UP',890,'已完结',NULL,NULL,3000,NULL,'2026-05-25 22:48:38','2026-05-31 14:19:48',0),(5,'Python 数据分析与可视化','https://wodiwodix-online-train-1259412410.cos.ap-guangzhou.myqcloud.com/images/2026/05/31/6185b374a848473e8b1eb6c076c9d5e4.svg','使用Pandas、NumPy、Matplotlib、Seaborn进行数据分析和可视化展示',3,'ONLINE',0.00,1,1,1,'UP',1520,'已完结',NULL,NULL,3000,NULL,'2026-05-25 22:48:38','2026-05-31 14:19:48',0),(6,'Django 企业级开发','https://wodiwodix-online-train-1259412410.cos.ap-guangzhou.myqcloud.com/images/2026/05/31/e71fe4b540a24bd38519868e40207a78.svg','Django REST Framework + Celery + Redis + Docker企业级项目实战',3,'ONLINE',129.00,0,2,0,'UP',340,'已完结',NULL,NULL,3000,NULL,'2026-05-25 22:48:38','2026-05-31 14:19:48',0),(7,'ChatGPT 应用开发实战','https://wodiwodix-online-train-1259412410.cos.ap-guangzhou.myqcloud.com/images/2026/05/31/d697fdbeef55476ba8690eeb0fbacfb5.svg','学习如何调用OpenAI API，开发智能聊天机器人、AI写作助手、代码生成器等应用',4,'ONLINE',299.00,0,1,1,'UP',1850,'更新中',NULL,NULL,3000,NULL,'2026-05-25 22:48:38','2026-05-31 14:19:48',0),(8,'LangChain 框架深度解析','https://wodiwodix-online-train-1259412410.cos.ap-guangzhou.myqcloud.com/images/2026/05/31/b6bba7aeb39642feacc1a24422702b33.svg','全面掌握LangChain框架，构建RAG应用、Agent智能体、多模态AI应用',4,'ONLINE',399.00,0,2,1,'UP',760,'更新中',NULL,NULL,3000,NULL,'2026-05-25 22:48:38','2026-05-31 14:19:48',0),(9,'MySQL 性能优化实战','https://wodiwodix-online-train-1259412410.cos.ap-guangzhou.myqcloud.com/images/2026/05/31/9ee9fde3d80a4d4cad3dd9d3a581bbc3.svg','索引优化、SQL调优、分库分表、主从复制、高可用架构一网打尽',5,'ONLINE',0.00,1,1,1,'UP',980,'已完结',NULL,NULL,3000,NULL,'2026-05-25 22:48:38','2026-05-31 14:19:48',0),(10,'Redis 深度剖析','https://wodiwodix-online-train-1259412410.cos.ap-guangzhou.myqcloud.com/images/2026/05/31/fbc5a0d9cac94862baaecf50388cdeca.svg','Redis数据结构、持久化、哨兵、集群、缓存穿透/击穿/雪崩解决方案',5,'ONLINE',99.00,0,2,0,'UP',520,'已完结',NULL,NULL,3000,NULL,'2026-05-25 22:48:38','2026-05-31 14:19:48',0),(11,'Docker + K8s 云原生入门','https://wodiwodix-online-train-1259412410.cos.ap-guangzhou.myqcloud.com/images/2026/05/31/d19ff1750ace4c9d9914546780f10726.svg','从Docker基础到Kubernetes编排，手把手教你构建云原生应用',6,'ONLINE',0.00,1,1,1,'UP',1100,'已完结',NULL,NULL,3000,NULL,'2026-05-25 22:48:38','2026-05-31 14:19:48',0),(12,'Jenkins + GitLab CI/CD 实战','https://wodiwodix-online-train-1259412410.cos.ap-guangzhou.myqcloud.com/images/2026/05/31/87d47aeef36e42fb91303a50cfc6d266.svg','搭建企业级CI/CD流水线，自动化构建、测试、部署全流程',6,'ONLINE',89.00,0,2,1,'UP',430,'已完结',NULL,NULL,3000,NULL,'2026-05-25 22:48:38','2026-05-31 14:19:48',0),(13,'线下打卡测试','https://wodiwodix-online-train-1259412410.cos.ap-guangzhou.myqcloud.com/images/2026/05/31/ae2091799c51482fbafa54f9f5141128.svg','',17,'OFFLINE',0.00,1,0,0,'UP',0,NULL,NULL,NULL,3000,1,NULL,'2026-05-31 14:19:48',0);
