DROP TABLE IF EXISTS `question`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `question` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `course_id` bigint(20) DEFAULT NULL COMMENT '课程ID',
  `chapter_id` bigint(20) DEFAULT NULL COMMENT '章节ID',
  `type` enum('SINGLE','MULTIPLE','JUDGE','ESSAY') NOT NULL COMMENT '题型',
  `content` text NOT NULL COMMENT '题目内容',
  `score` int(11) DEFAULT '1' COMMENT '分值',
  `answer` text COMMENT '答案',
  `analysis` text COMMENT '解析',
  `status` tinyint(4) DEFAULT '1' COMMENT '状态 1启用 0禁用',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint(4) DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=284 DEFAULT CHARSET=utf8mb4 COMMENT='题目表';
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `question` WRITE;
/*!40000 ALTER TABLE `question` DISABLE KEYS */;
INSERT INTO `question` VALUES (1,1,1,'SINGLE','Spring Boot 的核心特性不包括以下哪项？',2,'D','Spring Boot 核心特性包括自动配置、起步依赖、Actuator监控和内嵌服务器，不包括ORM框架，ORM框架是独立的',1,'2026-05-25 22:48:38',0),(2,1,2,'SINGLE','@SpringBootApplication 注解包含以下哪些注解？',2,'A','@SpringBootApplication = @Configuration + @EnableAutoConfiguration + @ComponentScan',1,'2026-05-25 22:48:38',0),(3,1,3,'SINGLE','Spring Boot 默认内嵌的Web服务器是？',2,'B','Spring Boot默认内嵌Tomcat，也支持Jetty和Undertow',1,'2026-05-25 22:48:38',0),(4,1,4,'SINGLE','MyBatis-Plus 中逻辑删除使用的注解是？',2,'C','@TableLogic 是MyBatis-Plus的逻辑删除注解',1,'2026-05-25 22:48:38',0),(5,1,5,'MULTIPLE','Spring Security 支持以下哪些认证方式？',3,'ABCD','Spring Security支持表单登录、JWT、OAuth2和LDAP认证',1,'2026-05-25 22:48:38',0),(6,1,6,'JUDGE','Spring Boot 2.x 默认使用 Java 8 作为最低版本要求',1,'T','Spring Boot 2.x 要求 Java 8 及以上版本',1,'2026-05-25 22:48:38',0),(7,3,1,'SINGLE','Vue3 中 Composition API 的入口函数是？',2,'B','setup() 是Composition API的入口函数，在组件创建之前执行',1,'2026-05-25 22:48:38',0),(8,3,2,'SINGLE','ref 和 reactive 的主要区别是？',2,'C','ref用于基本类型和对象，reactive仅用于对象类型。ref需要通过.value访问',1,'2026-05-25 22:48:38',0),(9,3,3,'MULTIPLE','TypeScript 支持以下哪些类型？',3,'ABCD','TypeScript支持元组、枚举、联合类型和交叉类型等高级类型',1,'2026-05-25 22:48:38',0),(10,3,4,'SINGLE','Vue3 官方推荐的状态管理库是？',2,'D','Pinia 是 Vue3 官方推荐的状态管理库，是Vuex 5的替代方案',1,'2026-05-25 22:48:38',0),(11,3,5,'JUDGE','Vite 在生产环境中使用 Rollup 进行打包',1,'T','Vite 开发环境使用esbuild预构建，生产环境使用Rollup打包',1,'2026-05-25 22:48:38',0),(12,3,6,'ESSAY','请简述 Vue3 相比 Vue2 的主要改进点',5,'Composition API、性能提升、TypeScript支持、Teleport、Suspense、Fragment、Tree Shaking等','主要改进包括：更小的包体积、更快的渲染速度、更好的TS支持、新增组合式API等',1,'2026-05-25 22:48:38',0),(13,5,1,'SINGLE','Python 中用于科学计算的基础库是？',2,'A','NumPy 是 Python 科学计算的基础库，提供多维数组对象和数学函数',1,'2026-05-25 22:48:38',0),(14,5,2,'SINGLE','以下哪个方法可以创建 NumPy 全零数组？',2,'C','np.zeros() 用于创建全零数组，np.ones()创建全一数组，np.eye()创建单位矩阵',1,'2026-05-25 22:48:38',0),(15,5,3,'MULTIPLE','Pandas 中读取数据的常用方法包括？',3,'ABC','read_csv、read_excel、read_json 是Pandas常用读取方法，read_sql需要数据库连接',1,'2026-05-25 22:48:38',0),(16,5,4,'SINGLE','Matplotlib 中用于创建画布的函数是？',2,'B','plt.figure() 用于创建画布对象，subplot()用于创建子图区域',1,'2026-05-25 22:48:38',0),(17,5,5,'JUDGE','Seaborn 是基于 Matplotlib 的高级可视化库',1,'T','Seaborn 是基于 matplotlib 的统计数据可视化库，提供更美观的默认样式',1,'2026-05-25 22:48:38',0),(18,5,1,'ESSAY','请简述数据清洗的常用步骤',5,'缺失值处理、重复值处理、异常值检测与处理、数据类型转换、数据标准化','数据清洗是数据分析的前提，包括处理缺失值、重复值、异常值等步骤',1,'2026-05-25 22:48:38',0),(19,7,1,'SINGLE','OpenAI API 中控制输出随机性的参数是？',2,'C','temperature 控制输出的随机性，值越高越随机（0-2），越低越确定',1,'2026-05-25 22:48:38',0),(20,7,1,'SINGLE','GPT-4 的上下文窗口最大是多少 tokens？',2,'B','GPT-4 Turbo 的上下文窗口为 128K tokens',1,'2026-05-25 22:48:38',0),(21,7,2,'MULTIPLE','Prompt 工程中常用技巧包括？',3,'ABCD','few-shot、chain-of-thought、role-playing、zero-shot 都是Prompt工程常用技巧',1,'2026-05-25 22:48:38',0),(22,7,3,'JUDGE','Function Calling 功能可以让 GPT 调用外部API',1,'T','Function Calling 允许 GPT 根据对话内容决定是否调用预定义的函数/API',1,'2026-05-25 22:48:38',0),(23,7,4,'ESSAY','请描述如何构建一个基于RAG的智能知识问答系统',8,'需要包含文档加载、文本分割、向量化存储、检索增强生成等步骤','RAG系统核心组件：文档解析->文本分割->向量嵌入->向量数据库->检索->LLM生成',1,'2026-05-25 22:48:38',0),(24,9,1,'SINGLE','MySQL InnoDB 存储引擎的默认索引结构是？',2,'B','InnoDB 使用 B+Tree 作为默认索引结构',1,'2026-05-25 22:48:38',0),(25,9,2,'MULTIPLE','以下哪些操作会导致索引失效？',3,'ABCD','在索引列上使用函数、LIKE前模糊匹配、隐式类型转换、OR条件（非索引列）都会导致索引失效',1,'2026-05-25 22:48:38',0),(26,9,3,'SINGLE','EXPLAIN 命令中 type 字段的哪个值表示最优的查询类型？',2,'A','EXPLAIN中type字段从好到差：system > const > eq_ref > ref > range > index > ALL',1,'2026-05-25 22:48:38',0),(27,9,4,'JUDGE','MySQL主从复制可以同时提高读写性能',1,'T','主从复制可以提高读性能（读写分离），但写操作只能在主库进行',1,'2026-05-25 22:48:38',0),(28,9,1,'ESSAY','请简述数据库分库分表的常见方案',5,'水平分表、垂直分表、水平分库、垂直分库，以及常用的中间件如ShardingSphere','分库分表是解决大数据量性能瓶颈的常用方案，需根据业务场景选择',1,'2026-05-25 22:48:38',0),(29,2,7,'SINGLE','微服务架构相比单体架构的主要优势是？',2,'B','独立部署和扩展是微服务最核心的优势。',1,'2026-05-31 11:04:51',0),(30,2,7,'SINGLE','微服务间通信最常用的同步方式是？',2,'C','RESTful API + HTTP 最常用。',1,'2026-05-31 11:04:51',0),(31,2,7,'SINGLE','以下哪个不属于微服务架构的核心组件？',2,'D','SOAP 是传统 Web Service 协议。',1,'2026-05-31 11:04:51',0),(32,2,7,'MULTIPLE','微服务架构的常见挑战包括？',3,'ABC','分布式事务、通信复杂度、运维难度。',1,'2026-05-31 11:04:51',0),(33,2,7,'JUDGE','微服务架构中，每个服务应该拥有自己独立的数据库。',2,'0','微服务提倡数据去中心化。',1,'2026-05-31 11:04:51',0),(34,2,8,'SINGLE','Nacos 主要提供哪两大核心功能？',2,'A','服务发现和配置管理。',1,'2026-05-31 11:04:51',0),(35,2,8,'SINGLE','Nacos 配置修改后，客户端如何获取最新配置？',2,'B','Nacos 通过长轮询实时推送变更。',1,'2026-05-31 11:04:51',0),(36,2,8,'SINGLE','Nacos 中临时实例和持久化实例的区别是？',2,'D','临时实例靠心跳保活。',1,'2026-05-31 11:04:51',0),(37,2,8,'MULTIPLE','Nacos 支持哪些功能？',3,'ABC','服务发现、动态配置、DNS。',1,'2026-05-31 11:04:51',0),(38,2,8,'JUDGE','Nacos 可作为 Dubbo 和 Spring Cloud 的注册中心。',2,'0','同时支持两者。',1,'2026-05-31 11:04:51',0),(39,2,9,'SINGLE','Sentinel 的主要功能是？',2,'B','流量控制与熔断降级。',1,'2026-05-31 11:04:51',0),(40,2,9,'SINGLE','Sentinel 中 QPS 限流表示什么含义？',2,'A','QPS = 每秒请求数。',1,'2026-05-31 11:04:51',0),(41,2,9,'SINGLE','Sentinel 降级规则中，RT 指的是什么？',2,'C','RT = 平均响应时间(毫秒)。',1,'2026-05-31 11:04:51',0),(42,2,9,'MULTIPLE','Sentinel 支持哪些流量控制效果？',3,'ABD','快速失败、Warm Up、匀速排队。',1,'2026-05-31 11:04:51',0),(43,2,9,'JUDGE','Sentinel 规则可在运行时动态修改。',2,'0','无需重启应用。',1,'2026-05-31 11:04:51',0),(44,2,10,'SINGLE','Spring Cloud Gateway 基于哪个框架构建？',2,'D','基于 Spring WebFlux (Reactor/Netty)。',1,'2026-05-31 11:04:51',0),(45,2,10,'SINGLE','Gateway 中过滤器(Filter)的作用是？',2,'A','对请求进行拦截处理，如鉴权、日志。',1,'2026-05-31 11:04:51',0),(46,2,10,'SINGLE','Gateway 路由断言(Predicate)的作用是？',2,'C','匹配请求是否满足路由条件。',1,'2026-05-31 11:04:51',0),(47,2,10,'MULTIPLE','Gateway 内置了哪些路由断言工厂？',3,'ABC','Path、Header、Query。',1,'2026-05-31 11:04:51',0),(48,2,10,'JUDGE','Gateway 可实现统一的跨域(CORS)处理和请求限流。',2,'0','可在网关层统一处理。',1,'2026-05-31 11:04:51',0),(49,2,11,'SINGLE','Seata 主要解决什么问题？',2,'B','分布式事务。',1,'2026-05-31 11:04:51',0),(50,2,11,'SINGLE','Seata AT 模式基于什么原理实现？',2,'A','两阶段提交，通过 undo_log 实现回滚。',1,'2026-05-31 11:04:51',0),(51,2,11,'SINGLE','Seata 中 TC 组件的全称是？',2,'C','TC = Transaction Coordinator。',1,'2026-05-31 11:04:51',0),(52,2,11,'MULTIPLE','Seata 支持哪些事务模式？',3,'ABD','AT、TCC、SAGA、XA 四种模式。',1,'2026-05-31 11:04:51',0),(53,2,11,'JUDGE','Seata AT 模式下需额外创建 undo_log 表。',2,'0','用于记录数据快照。',1,'2026-05-31 11:04:51',0),(54,