/*!40000 ALTER TABLE `system_config` DISABLE KEYS */;
INSERT INTO `system_config` VALUES (1,'about_us','<p style=\"text-align: center;\"><br></p><p style=\"text-align: center;\">在线学习平台，致力于提供优质的在线教育服务。</p><p style=\"text-align: center;\"> &nbsp; &nbsp;本平台是一站式实用技能线上学习服务平台，聚焦职场提升、兴趣拓展、副业创收三大学习方向，面向学生、职场从业者、技能爱好者打造轻量化、系统化的线上授课环境。平台汇聚各行各业资深讲师，课程覆盖办公技能、编程设计、新媒体运营、财会考证、手工技艺、语言学习、职业资质等全品类内容，兼顾零基础入门与高阶精进课程。</p><p style=\"text-align: center;\">依托碎片化授课、直播精讲 + 录播回看、课后作业答疑、实操配套素材、阶段性测评的闭环教学模式，打破地域与时间限制，用户可随时随地按需选课学习。平台配套学习社群、讲师一对一答疑、项目实战演练、就业副业指导等附加服务，摒弃冗余理论，以落地实用为核心，助力学习者快速掌握可落地、能变现的专业技能。同时搭建学员成果展示板块，联动行业资源，为学有所成的用户对接实习、兼职机会，打造从课程学习到技能落地的完整成长链路，成为大众低成本高效提升自我的优选学习阵地。</p>','2026-05-31 14:52:43','2026-05-31 14:52:43');
/*!40000 ALTER TABLE `system_config` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `user` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `phone` varchar(20) DEFAULT NULL COMMENT '手机号',
  `nickname` varchar(50) DEFAULT NULL COMMENT '昵称',
  `avatar` varchar(500) DEFAULT NULL COMMENT '头像',
  `openid` varchar(100) DEFAULT NULL COMMENT '微信openid',
  `password` varchar(200) DEFAULT NULL COMMENT '密码',
  `role` enum('ADMIN','STUDENT') DEFAULT 'STUDENT' COMMENT '角色',
  `status` tinyint(4) DEFAULT '1' COMMENT '状态 1正常 0禁用',
  `approval_status` varchar(20) DEFAULT 'APPROVED' COMMENT '审核状态',
  `real_name` varchar(50) DEFAULT NULL COMMENT '真实姓名',
  `gender` varchar(10) DEFAULT NULL COMMENT '性别',
  `age` int(11) DEFAULT NULL COMMENT '年龄',
  `education` varchar(50) DEFAULT NULL COMMENT '学历',
  `major` varchar(100) DEFAULT NULL COMMENT '专业',
  `register_time` datetime DEFAULT NULL COMMENT '注册时间',
  `total_study_duration` bigint(20) DEFAULT '0' COMMENT '总学习时长(秒)',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(4) DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COMMENT='用户表';
